def game(A, B):
    if A <= 0 and B <= 0:
        return "Non-drinkers can't play"

    mike_total = 0
    joe_total = 0
    turn = 0

    while True:
        if turn % 2 == 0:  # Mike's turn
            if mike_total + (turn // 2 + 1) > A:
                return "Joe"
            mike_total += turn // 2 + 1
        else:  # Joe's turn
            if joe_total + (turn // 2 + 2) > B:
                return "Mike"
            joe_total += turn // 2 + 2
        turn += 1
